import React, { useState } from 'react';
import { Card, CardContent } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Avatar, AvatarFallback } from '../ui/avatar';
import {
  Plus,
  Clock,
  Circle,
  Eye,
  Calendar,
  User,
  CheckCircle2,
} from 'lucide-react';
import { formatDate } from '../../utils/formatters';

const COLUMNS = [
  { id: 'todo', title: 'Por Hacer', icon: Circle, color: 'bg-gray-100 text-gray-700' },
  { id: 'in_progress', title: 'En Progreso', icon: Clock, color: 'bg-blue-100 text-blue-700' },
  { id: 'review', title: 'En Revisión', icon: Eye, color: 'bg-yellow-100 text-yellow-700' },
  { id: 'completed', title: 'Completado', icon: CheckCircle2, color: 'bg-green-100 text-green-700' },
];

const PRIORITY_COLORS = {
  low: 'bg-gray-100 text-gray-700',
  medium: 'bg-blue-100 text-blue-700',
  high: 'bg-orange-100 text-orange-700',
  urgent: 'bg-red-100 text-red-700',
};

const PRIORITY_LABELS = {
  low: 'Baja',
  medium: 'Media',
  high: 'Alta',
  urgent: 'Urgente',
};

export const KanbanBoard = ({ tasks = [], onTaskClick, onAddTask, onTaskMove, readOnly = false }) => {
  const [draggedTask, setDraggedTask] = useState(null);
  const [dragOverColumn, setDragOverColumn] = useState(null);

  // ✅ DRAG START - Guardar tarea que se está arrastrando
  const handleDragStart = (e, task) => {
    if (readOnly) return;
    
    setDraggedTask(task);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/html', e.currentTarget);
    
    // Agregar clase visual
    e.currentTarget.style.opacity = '0.5';
  };

  // ✅ DRAG END - Limpiar estado visual
  const handleDragEnd = (e) => {
    e.currentTarget.style.opacity = '1';
    setDraggedTask(null);
    setDragOverColumn(null);
  };

  // ✅ DRAG OVER - Permitir drop y visual feedback
  const handleDragOver = (e, columnId) => {
    if (!draggedTask || readOnly) return;
    
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setDragOverColumn(columnId);
  };

  // ✅ DRAG LEAVE - Limpiar visual feedback
  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  // ✅ DROP - Mover tarea a nueva columna
  const handleDrop = (e, columnId) => {
    e.preventDefault();
    
    if (!draggedTask || readOnly) {
      setDragOverColumn(null);
      return;
    }
    
    // Solo mover si cambió de columna
    if (draggedTask.status !== columnId) {
      onTaskMove?.(draggedTask._id, columnId);
    }
    
    setDraggedTask(null);
    setDragOverColumn(null);
  };

  const getTasksByStatus = (status) => {
    return tasks.filter(task => task.status === status);
  };

  const TaskCard = ({ task }) => {
    const completedSubtasks = task.subtasks?.filter(st => st.completed).length || 0;
    const totalSubtasks = task.subtasks?.length || 0;
    const hasSubtasks = totalSubtasks > 0;

    return (
      <Card
        draggable={!readOnly}
        onDragStart={(e) => handleDragStart(e, task)}
        onDragEnd={handleDragEnd}
        onClick={() => onTaskClick?.(task)}
        className={`cursor-pointer hover:shadow-lg transition-all mb-3 ${
          draggedTask?._id === task._id ? 'opacity-50 scale-95' : ''
        } ${readOnly ? 'cursor-default' : 'cursor-grab active:cursor-grabbing'}`}
      >
        <CardContent className="p-4">
          {/* Header con prioridad */}
          <div className="flex items-start justify-between mb-2">
            <div className="flex-1 min-w-0">
              <h4 className="font-semibold text-sm mb-1 truncate">
                {task.title}
              </h4>
              {task.description && (
                <p className="text-xs text-gray-500 line-clamp-2">
                  {task.description}
                </p>
              )}
            </div>
            <Badge className={`${PRIORITY_COLORS[task.priority]} text-xs ml-2 flex-shrink-0`}>
              {PRIORITY_LABELS[task.priority]}
            </Badge>
          </div>

          {/* Subtasks Progress */}
          {hasSubtasks && (
            <div className="mb-2">
              <div className="flex items-center justify-between text-xs text-gray-600 mb-1">
                <span>Subtareas</span>
                <span>{completedSubtasks}/{totalSubtasks}</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-1.5">
                <div
                  className="bg-green-500 h-1.5 rounded-full transition-all"
                  style={{ width: `${(completedSubtasks / totalSubtasks) * 100}%` }}
                />
              </div>
            </div>
          )}

          {/* Tags */}
          {task.tags && task.tags.length > 0 && (
            <div className="flex flex-wrap gap-1 mb-2">
              {task.tags.slice(0, 3).map((tag, idx) => (
                <Badge key={idx} variant="outline" className="text-xs">
                  {tag}
                </Badge>
              ))}
              {task.tags.length > 3 && (
                <Badge variant="outline" className="text-xs">
                  +{task.tags.length - 3}
                </Badge>
              )}
            </div>
          )}

          {/* Footer */}
          <div className="flex items-center justify-between mt-3 pt-3 border-t">
            {/* Assigned User */}
            <div className="flex items-center space-x-2">
              {task.assigned_to ? (
                <>
                  <Avatar className="h-6 w-6">
                    <AvatarFallback className="text-xs">
                      {task.assigned_to.full_name?.split(' ').map(n => n[0]).join('') || '?'}
                    </AvatarFallback>
                  </Avatar>
                  <span className="text-xs text-gray-600 hidden sm:inline">
                    {task.assigned_to.full_name?.split(' ')[0]}
                  </span>
                </>
              ) : (
                <div className="flex items-center text-xs text-gray-400">
                  <User className="w-4 h-4 mr-1" />
                  Sin asignar
                </div>
              )}
            </div>

            {/* Due Date */}
            {task.due_date && (
              <div className={`flex items-center text-xs ${
                new Date(task.due_date) < new Date() && task.status !== 'completed'
                  ? 'text-red-600'
                  : 'text-gray-600'
              }`}>
                <Calendar className="w-3 h-3 mr-1" />
                {formatDate(task.due_date)}
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
      {COLUMNS.map((column) => {
        const columnTasks = getTasksByStatus(column.id);
        const ColumnIcon = column.icon;
        const isDragOver = dragOverColumn === column.id;

        return (
          <div
            key={column.id}
            className={`bg-gray-50 rounded-lg p-4 min-h-[500px] transition-all ${
              isDragOver ? 'bg-green-50 ring-2 ring-green-500 scale-[1.02]' : ''
            }`}
            onDragOver={(e) => handleDragOver(e, column.id)}
            onDragLeave={handleDragLeave}
            onDrop={(e) => handleDrop(e, column.id)}
          >
            {/* Column Header */}
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-2">
                <ColumnIcon className="w-5 h-5 text-gray-600" />
                <h3 className="font-semibold text-sm">{column.title}</h3>
                <Badge variant="outline" className="text-xs">
                  {columnTasks.length}
                </Badge>
              </div>
              {!readOnly && column.id === 'todo' && (
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => onAddTask?.(column.id)}
                  className="h-7 w-7 p-0"
                >
                  <Plus className="w-4 h-4" />
                </Button>
              )}
            </div>

            {/* Tasks */}
            <div className="space-y-3">
              {columnTasks.length === 0 ? (
                <div className="text-center py-8 text-gray-400 text-sm">
                  {isDragOver ? (
                    <div className="text-green-600 font-medium animate-pulse">
                      <Circle className="w-8 h-8 mx-auto mb-2" />
                      <p>Suelta aquí</p>
                    </div>
                  ) : column.id === 'todo' && !readOnly ? (
                    <div>
                      <Circle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                      <p>Arrastra tareas aquí</p>
                      <p className="text-xs mt-1">o crea una nueva</p>
                    </div>
                  ) : (
                    <div>
                      <ColumnIcon className="w-8 h-8 mx-auto mb-2 opacity-50" />
                      <p>Sin tareas</p>
                    </div>
                  )}
                </div>
              ) : (
                columnTasks.map((task) => (
                  <TaskCard key={task._id} task={task} />
                ))
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};
